package ama.api;
import com.fasterxml.jackson.core.*;import com.fasterxml.jackson.databind.*;import jakarta.servlet.http.HttpServletRequest;import java.io.*;import java.util.*;
final class MinutesWire {
 private static final ObjectMapper JSON=new ObjectMapper(JsonFactory.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(StreamReadConstraints.builder().maxNestingDepth(4).maxStringLength(1024).maxNumberLength(19).build()).build()).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);
 record Command(long expected,String template){}
 static Command command(HttpServletRequest request,boolean initial)throws IOException {return parse(request,initial?"INITIAL":"GENERATION");}
 static long intent(HttpServletRequest request)throws IOException{return parse(request,"INTENT").expected();}
 private static Command parse(HttpServletRequest request,String kind)throws IOException {boolean initial=kind.equals("INITIAL");if(request.getContentLengthLong()>1048576)throw new ama.contract.TranscriptContracts.Failure(413,"REQUEST_TOO_LARGE");byte[] bytes;try(var stream=request.getInputStream()){bytes=stream.readNBytes(1048577);}if(bytes.length>1048576)throw new ama.contract.TranscriptContracts.Failure(413,"REQUEST_TOO_LARGE");JsonNode node;try(var parser=JSON.getFactory().createParser(bytes)){int count=0;while(parser.nextToken()!=null)if(++count>32)throw new IllegalArgumentException("Too many command fields");node=JSON.readTree(bytes);}catch(com.fasterxml.jackson.core.JsonProcessingException malformed){throw new IllegalArgumentException("Malformed minutes request");}if(node==null||!node.isObject())throw new IllegalArgumentException("Object required");node.fieldNames().forEachRemaining(name->{if(!Set.of("expectedRevision","expectedRevisionToken").contains(name)&&!(initial?name.equals("templateRevisionId"):kind.equals("GENERATION")&&name.equals("scope")))throw new IllegalArgumentException("Unknown field");});if(kind.equals("GENERATION")){var scope=node.get("scope");if(scope==null||!scope.isTextual()||!"FULL".equals(scope.textValue()))throw new IllegalArgumentException("Exact FULL scope required");}String template=null;if(initial){var value=node.get("templateRevisionId");if(value==null||!value.isTextual())throw new IllegalArgumentException("Template revision required");template=value.textValue();ama.contract.MinutesContracts.uuid(template);}return new Command(HttpRevisionTokens.expected(node),template);}
}
